-- ДИАГНОСТИКА скорости панели (SQL Lab, база CHaaS, только чтение). Запустить ДВА раза подряд, прислать оба времени.
-- Только проверка версии данных из боевого SQL панели (16 таблиц, фильтр WHERE) — сколько стоит она.
SELECT
  (SELECT count() = 1 AND countIf(state = 'ready') = 1 FROM prod_proteus.pa_next_manifest) AS manifest_ready,
  (SELECT count() FROM (SELECT _pa_next_run AS r FROM prod_proteus.pa_next_adg_member UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_all_day UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_dash_acl UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_dash_bkt UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_dash_day UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_dash_meta UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_dict UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_emp_attrs UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_evd_day UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_login_map UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_md UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_pair UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_person_id_map UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_staff UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_staffx UNION ALL SELECT _pa_next_run AS r FROM prod_proteus.pa_next_viewer) WHERE ifNull(r, '') != (SELECT any(run_id) FROM prod_proteus.pa_next_manifest)) = 0 AS tables_ok
